<script setup lang="ts">
import type { NotificationItem } from '~/types/lapormas'
definePageMeta({ layout: 'app', middleware: 'auth', title: 'Notifikasi' })
const { state, currentUser, markNotificationRead, markAllNotificationsRead } = useLaporMas()
const notifications = computed<NotificationItem[]>(() => state.value.notifications.filter((n: NotificationItem) => n.userId === currentUser.value?.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt)))
const unread = computed(() => notifications.value.filter((n: NotificationItem) => !n.read).length)
const format = (value: string) => new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value))
function open(item: typeof notifications.value[number]) { markNotificationRead(item.id); navigateTo(item.link) }
</script>
<template><div class="page-stack"><div class="page-title-row"><div><div class="eyebrow">PUSAT INFORMASI</div><h1>Notifikasi</h1><p>Pembaruan status laporan dan aktivitas akun Anda.</p></div><button v-if="unread" class="btn btn-outline" @click="markAllNotificationsRead">Tandai semua dibaca</button></div><div class="notification-summary"><div><strong>{{ unread }}</strong><span>Belum dibaca</span></div><div><strong>{{ notifications.length }}</strong><span>Total notifikasi</span></div><p>Notifikasi simulasi ditampilkan di dalam prototipe ini. Izin push browser belum diaktifkan.</p></div><section class="panel notification-panel"><div v-if="notifications.length" class="notification-list"><button v-for="item in notifications" :key="item.id" class="notification-item" :class="{ unread: !item.read }" @click="open(item)"><span class="notification-symbol" :class="`notification-${item.kind}`">{{ item.kind === 'resolution' ? '✓' : item.kind === 'report' ? '▤' : item.kind === 'account' ? '▦' : '✳' }}</span><span class="notification-copy"><b>{{ item.title }}</b><span>{{ item.message }}</span><small>{{ format(item.createdAt) }}</small></span><i v-if="!item.read"></i><span class="notification-open">↗</span></button></div><EmptyState v-else title="Belum ada notifikasi" description="Pembaruan laporan akan muncul di halaman ini." icon="♧" /></section></div></template>
